import java.util.*;

class Solution {
    public int minimumOperations(int[] nums) {
        if (nums.length <= 1) {
            return 0;
        }
        Map<Integer, Integer> evenCounts = countParity(nums, 0);
        Map<Integer, Integer> oddCounts = countParity(nums, 1);
        int[][] topEven = topTwo(evenCounts);
        int[][] topOdd = topTwo(oddCounts);
        int bestKeep = 0;
        for (int[] evenChoice : topEven) {
            for (int[] oddChoice : topOdd) {
                if (evenChoice[0] != oddChoice[0]) {
                    bestKeep = Math.max(bestKeep, evenChoice[1] + oddChoice[1]);
                }
            }
        }
        return nums.length - bestKeep;
    }

    private Map<Integer, Integer> countParity(int[] nums, int start) {
        Map<Integer, Integer> counts = new HashMap<>();
        for (int i = start; i < nums.length; i += 2) {
            counts.merge(nums[i], 1, Integer::sum);
        }
        return counts;
    }

    private int[][] topTwo(Map<Integer, Integer> counts) {
        int[][] best = {{-1, 0}, {-2, 0}};
        for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
            if (entry.getValue() > best[0][1]) {
                best[1] = best[0];
                best[0] = new int[]{entry.getKey(), entry.getValue()};
            } else if (entry.getValue() > best[1][1]) {
                best[1] = new int[]{entry.getKey(), entry.getValue()};
            }
        }
        return best;
    }
}

class Solution {
    public int minimumOperations(int[] nums) {
        if (nums.length <= 1) {
            return 0;
        }
        int[] even = new int[100001];
        int[] odd = new int[100001];
        for (int i = 0; i < nums.length; i++) {
            if ((i & 1) == 0) {
                even[nums[i]]++;
            } else {
                odd[nums[i]]++;
            }
        }
        int[][] topEven = topTwo(even);
        int[][] topOdd = topTwo(odd);
        int bestKeep = 0;
        for (int[] evenChoice : topEven) {
            for (int[] oddChoice : topOdd) {
                if (evenChoice[0] != oddChoice[0]) {
                    bestKeep = Math.max(bestKeep, evenChoice[1] + oddChoice[1]);
                }
            }
        }
        return nums.length - bestKeep;
    }

    private int[][] topTwo(int[] count) {
        int[][] best = {{-1, 0}, {-2, 0}};
        for (int value = 1; value < count.length; value++) {
            if (count[value] > best[0][1]) {
                best[1] = best[0];
                best[0] = new int[]{value, count[value]};
            } else if (count[value] > best[1][1]) {
                best[1] = new int[]{value, count[value]};
            }
        }
        return best;
    }
}

import java.util.*;

class Solution {
    public int minimumOperations(int[] nums) {
        int[][] topEven = topTwo(nums, 0);
        int[][] topOdd = topTwo(nums, 1);
        if (topEven[0][0] != topOdd[0][0]) {
            return nums.length - topEven[0][1] - topOdd[0][1];
        }
        int keepIfOddChanges = topEven[0][1] + topOdd[1][1];
        int keepIfEvenChanges = topEven[1][1] + topOdd[0][1];
        return nums.length - Math.max(keepIfOddChanges, keepIfEvenChanges);
    }

    private int[][] topTwo(int[] nums, int start) {
        Map<Integer, Integer> counts = new HashMap<>();
        for (int i = start; i < nums.length; i += 2) {
            counts.put(nums[i], counts.getOrDefault(nums[i], 0) + 1);
        }
        int[][] best = {{-1, 0}, {-2, 0}};
        for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
            if (entry.getValue() > best[0][1]) {
                best[1] = best[0];
                best[0] = new int[]{entry.getKey(), entry.getValue()};
            } else if (entry.getValue() > best[1][1]) {
                best[1] = new int[]{entry.getKey(), entry.getValue()};
            }
        }
        return best;
    }
}

import java.util.*;

class Solution {
    public int minimumOperations(int[] nums) {
        if (nums.length <= 1) {
            return 0;
        }
        List<int[]> evenCandidates = sortedCandidates(nums, 0, -1);
        List<int[]> oddCandidates = sortedCandidates(nums, 1, -2);
        int best = 0;
        for (int[] evenChoice : evenCandidates) {
            if (evenChoice[1] + oddCandidates.get(0)[1] <= best) {
                break;
            }
            for (int[] oddChoice : oddCandidates) {
                if (evenChoice[1] + oddChoice[1] <= best) {
                    break;
                }
                if (evenChoice[0] != oddChoice[0]) {
                    best = evenChoice[1] + oddChoice[1];
                    break;
                }
            }
        }
        return nums.length - best;
    }

    private List<int[]> sortedCandidates(int[] nums, int start, int sentinel) {
        Map<Integer, Integer> counts = new HashMap<>();
        for (int i = start; i < nums.length; i += 2) {
            counts.merge(nums[i], 1, Integer::sum);
        }
        List<int[]> candidates = new ArrayList<>();
        for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
            candidates.add(new int[]{entry.getKey(), entry.getValue()});
        }
        candidates.add(new int[]{sentinel, 0});
        candidates.sort((a, b) -> Integer.compare(b[1], a[1]));
        return candidates;
    }
}

